import{_ as t,c as o,o as d,ae as r}from"./chunks/framework.DCU7Csu6.js";const k=JSON.parse('{"title":"Миграция управления остатками: sku → chrtId","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/stocks-sku-to-chrtid-migration.md","filePath":"ru/guides/stocks-sku-to-chrtid-migration.md"}'),c={name:"ru/guides/stocks-sku-to-chrtid-migration.md"};function a(s,e,i,l,h,n){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="миграция-управления-остатками-sku-→-chrtid" tabindex="-1">Миграция управления остатками: <code>sku</code> → <code>chrtId</code> <a class="header-anchor" href="#миграция-управления-остатками-sku-→-chrtid" aria-label="Permalink to &quot;Миграция управления остатками: `sku` → `chrtId`&quot;">​</a></h1><blockquote><p><strong>Статус</strong>: Заглушка — полное руководство по миграции будет опубликовано в task-16.5 (v3.12.0).</p><p><strong>Жёсткий дедлайн</strong>: 2026-05-20 13:00 МСК — Wildberries начинает постепенно отключать параметр <code>sku</code> на эндпоинтах управления остатками. После дедлайна: HTTP 400 от WB.</p></blockquote><h2 id="почему-это-важно" tabindex="-1">Почему это важно <a class="header-anchor" href="#почему-это-важно" aria-label="Permalink to &quot;Почему это важно&quot;">​</a></h2><p>WB объявил 2026-05-08 (<a href="https://dev.wildberries.ru/release-notes?id=522" target="_blank" rel="noreferrer">https://dev.wildberries.ru/release-notes?id=522</a>) о том, что параметр <code>sku</code> (штрихкод) на трёх эндпоинтах управления остатками выводится из использования в пользу <code>chrtId</code> (ID размера из <code>POST /content/v2/get/cards/list</code>).</p><p>SDK v3.12.0 добавляет поддержку <code>chrtId</code> / <code>chrtIds</code> в:</p><ul><li><code>sdk.products.getStocks(warehouseId, { chrtIds: [...] })</code></li><li><code>sdk.products.updateStock(warehouseId, { stocks: [{ chrtId, amount }] })</code></li><li><code>sdk.products.deleteStock(warehouseId, { chrtIds: [...] })</code></li></ul><p>Устаревшие параметры <code>sku</code>/<code>skus</code> остаются принимаемыми (обратная совместимость), но помечены как <code>@deprecated</code> и будут вызывать <code>console.warn</code> (начиная с v3.12.0). Они будут УДАЛЕНЫ в будущей мажорной версии.</p><h2 id="как-получить-chrtid" tabindex="-1">Как получить <code>chrtId</code> <a class="header-anchor" href="#как-получить-chrtid" aria-label="Permalink to &quot;Как получить `chrtId`&quot;">​</a></h2><p>Вызовите <code>POST /content/v2/get/cards/list</code> и считайте поле <code>chrtID</code> из массива <code>sizes[]</code> каждой карточки. SDK предоставляет доступ через <code>sdk.products.getCardsList()</code>.</p><p><strong>Примечание о регистре</strong>: WB использует <code>chrtID</code> (заглавная D) в ответах Content API, но <code>chrtId</code> (строчная d) в эндпоинте остатков Marketplace. Передавайте то же числовое значение; свойство SDK — <code>chrtId</code> (строчная d) для методов работы с остатками.</p><h2 id="полные-шаги-миграции" tabindex="-1">Полные шаги миграции <a class="header-anchor" href="#полные-шаги-миграции" aria-label="Permalink to &quot;Полные шаги миграции&quot;">​</a></h2><p>(см. task-16.5 — эта заглушка будет заменена полным руководством.)</p><h2 id="связанные-ресурсы" tabindex="-1">Связанные ресурсы <a class="header-anchor" href="#связанные-ресурсы" aria-label="Permalink to &quot;Связанные ресурсы&quot;">​</a></h2><ul><li><a href="./../../CHANGELOG.html">CHANGELOG v3.12.0</a></li><li>Источник: <a href="https://dev.wildberries.ru/release-notes?id=522" target="_blank" rel="noreferrer">WB release-notes id=522</a></li></ul>',14)])])}const p=t(c,[["render",a]]);export{k as __pageData,p as default};
